import { useEffect, useMemo, useState } from 'react';
import {
    Box,
    TextField,
    Button,
    Typography,
    Paper,
} from '@mui/material';
import axios from 'axios';

const endpointMapping = {
    'Notion': 'notion',
    'Airtable': 'airtable',
    'HubSpot': 'hubspot',
};

const miniCardStyle = { p: 2, minWidth: 180, flex: 1 };

export const DataForm = ({ integrationType, credentials, aiMode }) => {
    const [loadedData, setLoadedData] = useState(null);
    const [insights, setInsights] = useState(null);
    const [llmInsights, setLlmInsights] = useState(null);
    const [series, setSeries] = useState([]);
    const endpoint = endpointMapping[integrationType];

    const parsedLoaded = useMemo(() => {
        if (!loadedData) return [];
        try {
            return JSON.parse(loadedData);
        } catch {
            return [];
        }
    }, [loadedData]);

    useEffect(() => {
        if (!aiMode) return undefined;
        const timer = window.setInterval(() => {
            const point = parsedLoaded.length + Math.floor(Math.random() * 3);
            setSeries((prev) => [...prev.slice(-14), point]);
        }, 1200);
        return () => window.clearInterval(timer);
    }, [aiMode, parsedLoaded.length]);

    const handleLoad = async () => {
        try {
            const formData = new FormData();
            formData.append('credentials', JSON.stringify(credentials));
            const response = await axios.post(`http://localhost:8000/integrations/${endpoint}/load`, formData);
            const data = response.data;
            setLoadedData(JSON.stringify(data, null, 2));
            setInsights(null);
            setLlmInsights(null);
        } catch (e) {
            alert(e?.response?.data?.detail);
        }
    };

    const handleInsights = async () => {
        try {
            if (!loadedData) {
                alert('Load integration data before generating insights.');
                return;
            }
            const formData = new FormData();
            formData.append('integration_type', integrationType);
            formData.append('items', loadedData);
            const response = await axios.post('http://localhost:8000/integrations/insights', formData);
            setInsights(JSON.stringify(response.data, null, 2));
        } catch (e) {
            alert(e?.response?.data?.detail);
        }
    };

    const handleLlmInsights = async () => {
        try {
            if (!loadedData) {
                alert('Load integration data before generating LLM insights.');
                return;
            }
            const formData = new FormData();
            formData.append('integration_type', integrationType);
            formData.append('items', loadedData);
            const response = await axios.post('http://localhost:8000/integrations/insights/llm', formData);
            setLlmInsights(JSON.stringify(response.data, null, 2));
        } catch (e) {
            alert(e?.response?.data?.detail);
        }
    };

    const clearAll = () => {
        setLoadedData(null);
        setInsights(null);
        setLlmInsights(null);
        setSeries([]);
    };

    if (!aiMode) {
        return (
            <Box display='flex' justifyContent='center' alignItems='center' flexDirection='column' width='100%'>
                <Box display='flex' flexDirection='column' width='100%'>
                    <TextField label="Loaded Data" value={loadedData || ''} sx={{mt: 2}} InputLabelProps={{ shrink: true }} disabled />
                    <Button onClick={handleLoad} sx={{mt: 2}} variant='contained'>Load Data</Button>
                    <Button onClick={clearAll} sx={{mt: 1}} variant='contained'>Clear Data</Button>
                </Box>
            </Box>
        );
    }

    return (
        <Box sx={{ width: 'min(1000px, 92vw)', mt: 2 }}>
            <Typography variant='h6' sx={{ mb: 1 }}>AI Insights Dashboard</Typography>
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                <Paper elevation={2} sx={miniCardStyle}>
                    <Typography variant='body2'>Integration</Typography>
                    <Typography variant='h6'>{integrationType}</Typography>
                </Paper>
                <Paper elevation={2} sx={miniCardStyle}>
                    <Typography variant='body2'>Items Loaded</Typography>
                    <Typography variant='h6'>{parsedLoaded.length}</Typography>
                </Paper>
                <Paper elevation={2} sx={miniCardStyle}>
                    <Typography variant='body2'>Live Signal</Typography>
                    <Typography variant='h6'>{series.length ? series[series.length - 1] : 0}</Typography>
                </Paper>
            </Box>

            <Paper elevation={2} sx={{ p: 2, mt: 2 }}>
                <Typography variant='subtitle1'>Live Graph</Typography>
                <Box sx={{ display: 'flex', alignItems: 'flex-end', gap: 0.5, height: 110, mt: 1 }}>
                    {series.map((value, idx) => (
                        <Box
                            key={`${value}-${idx}`}
                            sx={{
                                width: 10,
                                height: `${Math.min(100, value * 10)}%`,
                                background: 'linear-gradient(180deg, #00A86B, #0077B6)',
                                borderRadius: 0.5,
                            }}
                        />
                    ))}
                </Box>
            </Paper>

            <Box sx={{ display: 'flex', gap: 1, mt: 2, flexWrap: 'wrap' }}>
                <Button onClick={handleLoad} variant='contained'>Load Data</Button>
                <Button onClick={handleInsights} variant='contained' color='success'>Generate ML Insights</Button>
                <Button onClick={handleLlmInsights} variant='contained' color='secondary'>Generate LLM Insights (Gemini)</Button>
                <Button onClick={clearAll} variant='outlined'>Clear</Button>
            </Box>

            <TextField
                label="Loaded Data"
                value={loadedData || ''}
                sx={{mt: 2}}
                InputLabelProps={{ shrink: true }}
                disabled
                multiline
                minRows={5}
                fullWidth
            />
            <TextField
                label="ML Based Insights"
                value={insights || ''}
                sx={{mt: 2}}
                InputLabelProps={{ shrink: true }}
                disabled
                multiline
                minRows={5}
                fullWidth
            />
            <TextField
                label="LLM Based Insights (Gemini 2.5 Flash-Lite)"
                value={llmInsights || ''}
                sx={{mt: 2}}
                InputLabelProps={{ shrink: true }}
                disabled
                multiline
                minRows={6}
                fullWidth
            />
        </Box>
    );
};
